  var handle = null;
  var DEF = {"id":"p1","sceneId":"p1","title":"射孔参数优化","methods":["opt"],"version":"1.0.0","updated":"2026-11-05","status":"ready","tabs":{"background":{"label":"专业背景","judge":null,"lede":"射孔是连通井筒与储层的最后一枪，孔密、相位、穿深与弹型共同决定产能与出砂风险。","sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p>参数空间大，现场多沿用标准设计；不同储层用同一套参数，产能损失无法量化。<\/p>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>用代理模型 + 多目标优化，按储层条件推荐孔密、相位与穿深组合。<\/p>"},{"no":3,"en":"DATA","title":"需要准备什么","html":"<p>· 储层与力学参数：应力、强度、渗透率（无需标注）<\/p><p>· 射孔方案与测试产量：历史井数据（200—500 井次）<\/p><p>· 出砂与作业反馈：出砂、措施记录（约束条件）<\/p>"},{"no":4,"en":"DIFFICULTY","title":"难度与参考方向","html":"<p>难度：中。与完井参数设计高度重叠，横跨完井与射孔，建议合并建模、分场景展示。<\/p><p>参考方向：代理模型、多目标优化、实验设计。<\/p><p>交叉环节：完井。<\/p>"}]},"workflow":null}};
